import { notFound } from "next/navigation"; import { requireApprovedSession } from "@/lib/auth/guards"; import { createSupabaseServerClient } from "@/lib/supabase/server"; import { PartsList } from "@/components/maintenance/parts-list"; import { TirePositions } from "@/components/maintenance/tire-positions";
export default async function UnitMaintenancePage({params}:{params:Promise<{unitId:string}>}){await requireApprovedSession();const {unitId}=await params;const s=await createSupabaseServerClient();const [{data:unit},{data:parts},{data:tires}]=await Promise.all([s.from("units").select("body_number").eq("id",unitId).maybeSingle(),s.from("part_replacements").select("id,part_name,next_due_date,next_due_mileage").eq("unit_id",unitId).is("deleted_at",null),s.from("tire_installations").select("id,position,brand").eq("unit_id",unitId).is("deleted_at",null).is("replaced_by_id",null)]);if(!unit)notFound();return <section className="mx-auto w-full max-w-3xl space-y-6 px-4 py-6"><h1 className="text-2xl font-semibold">Body {unit.body_number} maintenance</h1><div><h2 className="font-semibold">Parts</h2><PartsList parts={parts??[]}/></div><div><h2 className="font-semibold">Current tires</h2><TirePositions tires={tires??[]}/></div></section>}
